1	package meter
2	
3	import (
4		"errors"
5		"testing"
6	)
7	
8	// 账期内预计费用查询（EstimateCurrentBill）的回归测试。
9	// 预估必须：只针对当前 UTC 自然月、只统计已接收用量、沿用正式出账计价、
10	// 明确标为预估、纯读无副作用；待生效换套餐不提前混入；等待取消与欠费
11	// 停用期间可查；不可预估的情况返回各自已有错误；溢出返回 ErrOverflow。
12	
13	// wantEstimate 逐项核对预估结果。
14	func wantEstimate(t *testing.T, e EstimatedBill, want EstimatedBill) {
15		t.Helper()
16		if !e.Estimated {
17			t.Fatalf("estimate must be marked Estimated=true: %+v", e)
18		}
19		if e.AccountID != want.AccountID || e.Period != want.Period || e.Terms != want.Terms ||
20			e.TotalUsage != want.TotalUsage || e.IncludedUnits != want.IncludedUnits ||
21			e.OverageUnits != want.OverageUnits || e.MonthlyFee != want.MonthlyFee ||
22			e.OverageFee != want.OverageFee || e.Tax != want.Tax ||
23			e.EstimatedTotalDue != want.EstimatedTotalDue {
24			t.Fatalf("estimate:\n got %+v\nwant %+v", e, want)
25		}
26	}
27	
28	func planTerms(id string, fee, included, overage, rate int64) PlanTerms {
29		return PlanTerms{PlanID: id, MonthlyFee: fee, IncludedUnits: included,
30			OveragePrice: overage, TaxRateBasisPoints: rate}
31	}
32	
33	func TestEstimateCurrentBillPricing(t *testing.T) {
34		s, clk := newTestService(utc(2026, 1, 15, 12, 0))
35		mustPlan(t, s, Plan{ID: "p", MonthlyFee: 1000, IncludedUnits: 10, OveragePrice: 100, TaxRateBasisPoints: 1000})
36		mustAccount(t, s, "a")
37		// 月中开通：预估仍收完整月费、给完整额度，不按天折算。
38		if err := s.Subscribe("a", "p", utc(2026, 1, 10, 12, 0)); err != nil {
39			t.Fatal(err)
40		}
41		jan26 := jan(2026)
42		terms := planTerms("p", 1000, 10, 100, 1000)
43	
44		// 没有任何用量也能查询：累计、超额为零，月费与税额照常（税 100）。
45		e, err := s.EstimateCurrentBill("a")
46		if err != nil {
47			t.Fatalf("estimate with no usage: %v", err)
48		}
49		wantEstimate(t, e, EstimatedBill{
50			AccountID: "a", Estimated: true, Period: jan26, Terms: terms,
51			TotalUsage: 0, IncludedUnits: 10, OverageUnits: 0,
52			MonthlyFee: 1000, OverageFee: 0, Tax: 100, EstimatedTotalDue: 1100,
53		})
54	
55		// 接收 15 单位：超额 5、超额费 500、税 150、预计应付 1650。
56		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "e1", At: utc(2026, 1, 12, 0, 0), Quantity: 15}); err != nil {
57			t.Fatal(err)
58		}
59		e, err = s.EstimateCurrentBill("a")
60		if err != nil {
61			t.Fatal(err)
62		}
63		wantEstimate(t, e, EstimatedBill{
64			AccountID: "a", Estimated: true, Period: jan26, Terms: terms,
65			TotalUsage: 15, IncludedUnits: 10, OverageUnits: 5,
66			MonthlyFee: 1000, OverageFee: 500, Tax: 150, EstimatedTotalDue: 1650,
67		})
68	
69		// 账期未结束时仍不能正式出账：预估没有把当月关闭。
70		if _, err := s.CreateBill("a", jan26); !errors.Is(err, ErrBillMonthNotEnded) {
71			t.Fatalf("create bill mid-month: %v", err)
72		}
73	
74		// 账期结束后无新增用量时，正式出账与预估各项金额一致。
75		clk.t = utc(2026, 2, 1, 0, 0)
76		b, err := s.CreateBill("a", jan26)
77		if err != nil {
78			t.Fatal(err)
79		}
80		if b.Terms != e.Terms || b.TotalUsage != e.TotalUsage || b.IncludedUnits != e.IncludedUnits ||
81			b.OverageUnits != e.OverageUnits || b.MonthlyFee != e.MonthlyFee ||
82			b.OverageFee != e.OverageFee || b.Tax != e.Tax || b.TotalDue != e.EstimatedTotalDue {
83			t.Fatalf("formal bill diverges from estimate:\n bill %+v\n est  %+v", b, e)
84		}
85	}
