87	func TestEstimateCurrentBillTaxRounding(t *testing.T) {
88		s, _ := newTestService(utc(2026, 1, 15, 12, 0))
89		// 与正式出账相同的舍入：不足半分舍去、恰好半分向上。
90		cases := []struct {
91			name      string
92			fee       int64
93			wantTax   int64
94			wantTotal int64
95		}{
96			{"down", 4, 0, 4},
97			{"half", 5, 1, 6},
98		}
99		for _, c := range cases {
100			mustPlan(t, s, Plan{ID: "p-" + c.name, MonthlyFee: c.fee, IncludedUnits: 0, OveragePrice: 0, TaxRateBasisPoints: 1000})
101			mustAccount(t, s, c.name)
102			if err := s.Subscribe(c.name, "p-"+c.name, utc(2026, 1, 10, 0, 0)); err != nil {
103				t.Fatal(err)
104			}
105			e, err := s.EstimateCurrentBill(c.name)
106			if err != nil {
107				t.Fatalf("%s: %v", c.name, err)
108			}
109			if e.Tax != c.wantTax || e.EstimatedTotalDue != c.wantTotal {
110				t.Fatalf("%s: tax=%d due=%d, want tax=%d due=%d", c.name, e.Tax, e.EstimatedTotalDue, c.wantTax, c.wantTotal)
111			}
112		}
113	}
