183	func TestEstimateCurrentBillPendingPlanChangeNotMixed(t *testing.T) {
184		s, clk := newTestService(utc(2026, 1, 15, 12, 0))
185		mustPlan(t, s, Plan{ID: "p-a", MonthlyFee: 1000, IncludedUnits: 10, OveragePrice: 100, TaxRateBasisPoints: 1000})
186		mustPlan(t, s, Plan{ID: "p-b", MonthlyFee: 2000, IncludedUnits: 20, OveragePrice: 200, TaxRateBasisPoints: 600})
187		mustAccount(t, s, "a")
188		if err := s.Subscribe("a", "p-a", utc(2026, 1, 1, 0, 0)); err != nil {
189			t.Fatal(err)
190		}
191		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "e1", At: utc(2026, 1, 10, 0, 0), Quantity: 15}); err != nil {
192			t.Fatal(err)
193		}
194		if _, err := s.SchedulePlanChange("a", "p-b"); err != nil {
195			t.Fatal(err)
196		}
197		// 安排后再修改两个套餐的定义：订阅快照与安排快照都不应被改写。
198		if err := s.UpdatePlan(Plan{ID: "p-a", MonthlyFee: 9, IncludedUnits: 0, OveragePrice: 9, TaxRateBasisPoints: 0}); err != nil {
199			t.Fatal(err)
200		}
201		if err := s.UpdatePlan(Plan{ID: "p-b", MonthlyFee: 5000, IncludedUnits: 5, OveragePrice: 900, TaxRateBasisPoints: 2500}); err != nil {
202			t.Fatal(err)
203		}
204	
205		// 一月预估仍是旧条件，待生效安排不提前混入。
206		e, err := s.EstimateCurrentBill("a")
207		if err != nil {
208			t.Fatal(err)
209		}
210		if e.Terms != planTerms("p-a", 1000, 10, 100, 1000) || e.EstimatedTotalDue != 1650 {
211			t.Fatalf("january estimate mixed pending change: %+v", e)
212		}
213	
214		// 到二月月初后直接预估即用安排接受时锁定的条件，不依赖先上报用量。
215		clk.t = utc(2026, 2, 1, 0, 0)
216		e, err = s.EstimateCurrentBill("a")
217		if err != nil {
218			t.Fatal(err)
219		}
220		wantEstimate(t, e, EstimatedBill{
221			AccountID: "a", Estimated: true, Period: feb(2026),
222			Terms:         planTerms("p-b", 2000, 20, 200, 600),
223			TotalUsage:    0,
224			IncludedUnits: 20,
225			OverageUnits:  0,
226			MonthlyFee:    2000,
227			OverageFee:    0,
228			Tax:           120,
229			// 2000 × 6% = 120。
230			EstimatedTotalDue: 2120,
231		})
232	
233		// 二月接收 25 单位：超额按锁定单价 200 计 5 个单位，税按 6%。
234		clk.t = utc(2026, 2, 10, 0, 0)
235		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "e2", At: utc(2026, 2, 2, 0, 0), Quantity: 25}); err != nil {
236			t.Fatal(err)
237		}
238		e, err = s.EstimateCurrentBill("a")
239		if err != nil {
240			t.Fatal(err)
241		}
242		if e.TotalUsage != 25 || e.OverageUnits != 5 || e.OverageFee != 1000 || e.Tax != 180 || e.EstimatedTotalDue != 3180 {
243			t.Fatalf("february estimate with usage: %+v", e)
244		}
245	}
