247	func TestEstimateCurrentBillWhileCancelling(t *testing.T) {
248		s, clk := newTestService(utc(2026, 1, 15, 12, 0))
249		mustPlan(t, s, Plan{ID: "p", MonthlyFee: 1000, IncludedUnits: 10, OveragePrice: 100, TaxRateBasisPoints: 1000})
250		mustAccount(t, s, "a")
251		if err := s.Subscribe("a", "p", utc(2026, 1, 1, 0, 0)); err != nil {
252			t.Fatal(err)
253		}
254		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "e1", At: utc(2026, 1, 10, 0, 0), Quantity: 15}); err != nil {
255			t.Fatal(err)
256		}
257		if _, err := s.CancelSubscription("a"); err != nil {
258			t.Fatal(err)
259		}
260	
261		// 已登记按月取消但尚未到终止时刻：仍可查询，当月完整计费。
262		e, err := s.EstimateCurrentBill("a")
263		if err != nil {
264			t.Fatalf("estimate while cancelling failed: %v", err)
265		}
266		if !e.Estimated || e.MonthlyFee != 1000 || e.IncludedUnits != 10 ||
267			e.OverageFee != 500 || e.EstimatedTotalDue != 1650 {
268			t.Fatalf("estimate while cancelling: %+v", e)
269		}
270	
271		// 终止时刻到达后订阅已终止：返回无订阅错误，不输出预估。
272		clk.t = utc(2026, 2, 1, 0, 0)
273		if _, err := s.EstimateCurrentBill("a"); !errors.Is(err, ErrSubscriptionNotFound) {
274			t.Fatalf("estimate after cancellation end: %v", err)
275		}
276		// 预估失败不留账单；一月正式出账仍按完整月计。
277		b, err := s.CreateBill("a", jan(2026))
278		if err != nil {
279			t.Fatal(err)
280		}
281		if b.TotalDue != 1650 {
282			t.Fatalf("january bill after end: %+v", b)
283		}
284	}
