344	func TestEstimateCurrentBillErrors(t *testing.T) {
345		s, clk := newTestService(utc(2026, 1, 15, 12, 0))
346		mustPlan(t, s, Plan{ID: "p", MonthlyFee: 1000, IncludedUnits: 10, OveragePrice: 100, TaxRateBasisPoints: 1000})
347		mustAccount(t, s, "never")
348		mustAccount(t, s, "future")
349		mustAccount(t, s, "ended")
350		mustAccount(t, s, "gap")
351	
352		if err := s.Subscribe("future", "p", utc(2026, 1, 20, 12, 0)); err != nil {
353			t.Fatal(err)
354		}
355		if err := s.Subscribe("ended", "p", utc(2026, 1, 1, 0, 0)); err != nil {
356			t.Fatal(err)
357		}
358		if _, err := s.CancelSubscription("ended"); err != nil {
359			t.Fatal(err)
360		}
361	
362		if _, err := s.EstimateCurrentBill(""); !errors.Is(err, ErrInvalidArgument) {
363			t.Fatalf("empty id: %v", err)
364		}
365		if _, err := s.EstimateCurrentBill("ghost"); !errors.Is(err, ErrAccountNotFound) {
366			t.Fatalf("missing account: %v", err)
367		}
368		if _, err := s.EstimateCurrentBill("never"); !errors.Is(err, ErrSubscriptionNotFound) {
369			t.Fatalf("never subscribed: %v", err)
370		}
371		// 提前登记、开通时刻尚未到达：订阅尚未生效，不提前预估。
372		if _, err := s.EstimateCurrentBill("future"); !errors.Is(err, ErrSubscriptionNotActivated) {
373			t.Fatalf("future activation: %v", err)
374		}
375		// 开通当天零点仍未到登记的具体时刻：同样尚未生效。
376		clk.t = utc(2026, 1, 20, 0, 0)
377		if _, err := s.EstimateCurrentBill("future"); !errors.Is(err, ErrSubscriptionNotActivated) {
378			t.Fatalf("activation day midnight: %v", err)
379		}
380		// 恰好到达开通时刻即可预估。
381		clk.t = utc(2026, 1, 20, 12, 0)
382		if e, err := s.EstimateCurrentBill("future"); err != nil || !e.Estimated || e.MonthlyFee != 1000 {
383			t.Fatalf("estimate at activation instant: %+v %v", e, err)
384		}
385	
386		// 已登记取消、到达终止时刻后订阅终止。
387		clk.t = utc(2026, 2, 1, 0, 0)
388		if _, err := s.EstimateCurrentBill("ended"); !errors.Is(err, ErrSubscriptionNotFound) {
389			t.Fatalf("ended subscription: %v", err)
390		}
391	
392		// 旧订阅已终止、新订阅提前登记尚未开通：空档中按尚未生效处理。
393		if err := s.Subscribe("gap", "p", utc(2026, 2, 10, 0, 0)); err != nil {
394			// gap 账户没有旧订阅；直接登记未来开通即可。
395			t.Fatal(err)
396		}
397		clk.t = utc(2026, 2, 5, 0, 0)
398		if _, err := s.EstimateCurrentBill("gap"); !errors.Is(err, ErrSubscriptionNotActivated) {
399			t.Fatalf("gap before future resubscribe: %v", err)
400		}
401		clk.t = utc(2026, 2, 10, 0, 0)
402		if e, err := s.EstimateCurrentBill("gap"); err != nil || !e.Estimated {
403			t.Fatalf("estimate after future activation: %+v %v", e, err)
404		}
405	}
