package meter

import (
	"errors"
	"testing"
)

// 账期内预计费用查询（EstimateCurrentBill）的回归测试。
// 预估必须：只针对当前 UTC 自然月、只统计已接收用量、沿用正式出账计价、
// 明确标为预估、纯读无副作用；待生效换套餐不提前混入；等待取消与欠费
// 停用期间可查；不可预估的情况返回各自已有错误；溢出返回 ErrOverflow。

// wantEstimate 逐项核对预估结果。
func wantEstimate(t *testing.T, e EstimatedBill, want EstimatedBill) {
	t.Helper()
	if !e.Estimated {
		t.Fatalf("estimate must be marked Estimated=true: %+v", e)
	}
	if e.AccountID != want.AccountID || e.Period != want.Period || e.Terms != want.Terms ||
		e.TotalUsage != want.TotalUsage || e.IncludedUnits != want.IncludedUnits ||
		e.OverageUnits != want.OverageUnits || e.MonthlyFee != want.MonthlyFee ||
		e.OverageFee != want.OverageFee || e.Tax != want.Tax ||
		e.EstimatedTotalDue != want.EstimatedTotalDue {
		t.Fatalf("estimate:\n got %+v\nwant %+v", e, want)
	}
}

func planTerms(id string, fee, included, overage, rate int64) PlanTerms {
	return PlanTerms{PlanID: id, MonthlyFee: fee, IncludedUnits: included,
		OveragePrice: overage, TaxRateBasisPoints: rate}
}

func TestEstimateCurrentBillPricing(t *testing.T) {
	s, clk := newTestService(utc(2026, 1, 15, 12, 0))
	mustPlan(t, s, Plan{ID: "p", MonthlyFee: 1000, IncludedUnits: 10, OveragePrice: 100, TaxRateBasisPoints: 1000})
	mustAccount(t, s, "a")
	// 月中开通：预估仍收完整月费、给完整额度，不按天折算。
	if err := s.Subscribe("a", "p", utc(2026, 1, 10, 12, 0)); err != nil {
		t.Fatal(err)
	}
	jan26 := jan(2026)
	terms := planTerms("p", 1000, 10, 100, 1000)

	// 没有任何用量也能查询：累计、超额为零，月费与税额照常（税 100）。
	e, err := s.EstimateCurrentBill("a")
	if err != nil {
		t.Fatalf("estimate with no usage: %v", err)
	}
	wantEstimate(t, e, EstimatedBill{
		AccountID: "a", Estimated: true, Period: jan26, Terms: terms,
		TotalUsage: 0, IncludedUnits: 10, OverageUnits: 0,
		MonthlyFee: 1000, OverageFee: 0, Tax: 100, EstimatedTotalDue: 1100,
	})

	// 接收 15 单位：超额 5、超额费 500、税 150、预计应付 1650。
	if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "e1", At: utc(2026, 1, 12, 0, 0), Quantity: 15}); err != nil {
		t.Fatal(err)
	}
	e, err = s.EstimateCurrentBill("a")
	if err != nil {
		t.Fatal(err)
	}
	wantEstimate(t, e, EstimatedBill{
		AccountID: "a", Estimated: true, Period: jan26, Terms: terms,
		TotalUsage: 15, IncludedUnits: 10, OverageUnits: 5,
		MonthlyFee: 1000, OverageFee: 500, Tax: 150, EstimatedTotalDue: 1650,
	})

	// 账期未结束时仍不能正式出账：预估没有把当月关闭。
	if _, err := s.CreateBill("a", jan26); !errors.Is(err, ErrBillMonthNotEnded) {
		t.Fatalf("create bill mid-month: %v", err)
	}

	// 账期结束后无新增用量时，正式出账与预估各项金额一致。
	clk.t = utc(2026, 2, 1, 0, 0)
	b, err := s.CreateBill("a", jan26)
	if err != nil {
		t.Fatal(err)
	}
	if b.Terms != e.Terms || b.TotalUsage != e.TotalUsage || b.IncludedUnits != e.IncludedUnits ||
		b.OverageUnits != e.OverageUnits || b.MonthlyFee != e.MonthlyFee ||
		b.OverageFee != e.OverageFee || b.Tax != e.Tax || b.TotalDue != e.EstimatedTotalDue {
		t.Fatalf("formal bill diverges from estimate:\n bill %+v\n est  %+v", b, e)
	}
}

func TestEstimateCurrentBillTaxRounding(t *testing.T) {
	s, _ := newTestService(utc(2026, 1, 15, 12, 0))
	// 与正式出账相同的舍入：不足半分舍去、恰好半分向上。
	cases := []struct {
		name      string
		fee       int64
		wantTax   int64
		wantTotal int64
	}{
		{"down", 4, 0, 4},
		{"half", 5, 1, 6},
	}
	for _, c := range cases {
		mustPlan(t, s, Plan{ID: "p-" + c.name, MonthlyFee: c.fee, IncludedUnits: 0, OveragePrice: 0, TaxRateBasisPoints: 1000})
		mustAccount(t, s, c.name)
		if err := s.Subscribe(c.name, "p-"+c.name, utc(2026, 1, 10, 0, 0)); err != nil {
			t.Fatal(err)
		}
		e, err := s.EstimateCurrentBill(c.name)
		if err != nil {
			t.Fatalf("%s: %v", c.name, err)
		}
		if e.Tax != c.wantTax || e.EstimatedTotalDue != c.wantTotal {
			t.Fatalf("%s: tax=%d due=%d, want tax=%d due=%d", c.name, e.Tax, e.EstimatedTotalDue, c.wantTax, c.wantTotal)
		}
	}
}

func TestEstimateCurrentBillNoSideEffects(t *testing.T) {
	s, clk := newTestService(utc(2026, 1, 15, 12, 0))
	mustPlan(t, s, Plan{ID: "p", MonthlyFee: 1000, IncludedUnits: 10, OveragePrice: 100, TaxRateBasisPoints: 1000})
	mustAccount(t, s, "a")
	if err := s.Subscribe("a", "p", utc(2026, 1, 1, 0, 0)); err != nil {
		t.Fatal(err)
	}
	if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "e1", At: utc(2026, 1, 10, 0, 0), Quantity: 15}); err != nil {
		t.Fatal(err)
	}
	if _, err := s.EstimateCurrentBill("a"); err != nil {
		t.Fatal(err)
	}

	// 不保存正式账单。
	if _, err := s.GetBill("a", jan(2026)); !errors.Is(err, ErrBillNotFound) {
		t.Fatalf("estimate saved a bill: %v", err)
	}
	// 不改变用量。
	if u, _ := s.MonthlyUsage("a", jan(2026)); u.Total != 15 {
		t.Fatalf("usage changed after estimate: %d", u.Total)
	}
	// 不关闭当月：预估之后同月新用量照常接收，再次预估反映新增累计。
	clk.t = utc(2026, 1, 16, 0, 0)
	if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "e2", At: utc(2026, 1, 16, 0, 0), Quantity: 3}); err != nil {
		t.Fatalf("new usage after estimate rejected: %v", err)
	}
	e, err := s.EstimateCurrentBill("a")
	if err != nil {
		t.Fatal(err)
	}
	if e.TotalUsage != 18 || e.OverageUnits != 8 || e.OverageFee != 800 || e.EstimatedTotalDue != 1980 {
		t.Fatalf("estimate did not reflect new usage: %+v", e)
	}
	// 重复预估结果一致、不累积任何状态。
	e2, err := s.EstimateCurrentBill("a")
	if err != nil || e2 != e {
		t.Fatalf("repeated estimate differs: %+v %v", e2, err)
	}
	// 预估不影响状态中的账单列表。
	st, err := s.Status("a")
	if err != nil {
		t.Fatal(err)
	}
	if len(st.Bills) != 0 || st.Suspended {
		t.Fatalf("estimate changed status: %+v", st)
	}

	// 跨月后一月仍未出账、可正常出账；二月预估只看二月用量（0），
	// 不把一月用量带进来。
	clk.t = utc(2026, 2, 10, 0, 0)
	febEst, err := s.EstimateCurrentBill("a")
	if err != nil {
		t.Fatal(err)
	}
	if febEst.Period != feb(2026) || febEst.TotalUsage != 0 || febEst.OverageUnits != 0 ||
		febEst.MonthlyFee != 1000 || febEst.Tax != 100 {
		t.Fatalf("february estimate: %+v", febEst)
	}
	b, err := s.CreateBill("a", jan(2026))
	if err != nil {
		t.Fatal(err)
	}
	if b.TotalUsage != 18 {
		t.Fatalf("january bill usage = %d, want 18", b.TotalUsage)
	}
}

func TestEstimateCurrentBillPendingPlanChangeNotMixed(t *testing.T) {
	s, clk := newTestService(utc(2026, 1, 15, 12, 0))
	mustPlan(t, s, Plan{ID: "p-a", MonthlyFee: 1000, IncludedUnits: 10, OveragePrice: 100, TaxRateBasisPoints: 1000})
	mustPlan(t, s, Plan{ID: "p-b", MonthlyFee: 2000, IncludedUnits: 20, OveragePrice: 200, TaxRateBasisPoints: 600})
	mustAccount(t, s, "a")
	if err := s.Subscribe("a", "p-a", utc(2026, 1, 1, 0, 0)); err != nil {
		t.Fatal(err)
	}
	if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "e1", At: utc(2026, 1, 10, 0, 0), Quantity: 15}); err != nil {
		t.Fatal(err)
	}
	if _, err := s.SchedulePlanChange("a", "p-b"); err != nil {
		t.Fatal(err)
	}
	// 安排后再修改两个套餐的定义：订阅快照与安排快照都不应被改写。
	if err := s.UpdatePlan(Plan{ID: "p-a", MonthlyFee: 9, IncludedUnits: 0, OveragePrice: 9, TaxRateBasisPoints: 0}); err != nil {
		t.Fatal(err)
	}
	if err := s.UpdatePlan(Plan{ID: "p-b", MonthlyFee: 5000, IncludedUnits: 5, OveragePrice: 900, TaxRateBasisPoints: 2500}); err != nil {
		t.Fatal(err)
	}

	// 一月预估仍是旧条件，待生效安排不提前混入。
	e, err := s.EstimateCurrentBill("a")
	if err != nil {
		t.Fatal(err)
	}
	if e.Terms != planTerms("p-a", 1000, 10, 100, 1000) || e.EstimatedTotalDue != 1650 {
		t.Fatalf("january estimate mixed pending change: %+v", e)
	}

	// 到二月月初后直接预估即用安排接受时锁定的条件，不依赖先上报用量。
	clk.t = utc(2026, 2, 1, 0, 0)
	e, err = s.EstimateCurrentBill("a")
	if err != nil {
		t.Fatal(err)
	}
	wantEstimate(t, e, EstimatedBill{
		AccountID: "a", Estimated: true, Period: feb(2026),
		Terms:         planTerms("p-b", 2000, 20, 200, 600),
		TotalUsage:    0,
		IncludedUnits: 20,
		OverageUnits:  0,
		MonthlyFee:    2000,
		OverageFee:    0,
		Tax:           120,
		// 2000 × 6% = 120。
		EstimatedTotalDue: 2120,
	})

	// 二月接收 25 单位：超额按锁定单价 200 计 5 个单位，税按 6%。
	clk.t = utc(2026, 2, 10, 0, 0)
	if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "e2", At: utc(2026, 2, 2, 0, 0), Quantity: 25}); err != nil {
		t.Fatal(err)
	}
	e, err = s.EstimateCurrentBill("a")
	if err != nil {
		t.Fatal(err)
	}
	if e.TotalUsage != 25 || e.OverageUnits != 5 || e.OverageFee != 1000 || e.Tax != 180 || e.EstimatedTotalDue != 3180 {
		t.Fatalf("february estimate with usage: %+v", e)
	}
}

func TestEstimateCurrentBillWhileCancelling(t *testing.T) {
	s, clk := newTestService(utc(2026, 1, 15, 12, 0))
	mustPlan(t, s, Plan{ID: "p", MonthlyFee: 1000, IncludedUnits: 10, OveragePrice: 100, TaxRateBasisPoints: 1000})
	mustAccount(t, s, "a")
	if err := s.Subscribe("a", "p", utc(2026, 1, 1, 0, 0)); err != nil {
		t.Fatal(err)
	}
	if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "e1", At: utc(2026, 1, 10, 0, 0), Quantity: 15}); err != nil {
		t.Fatal(err)
	}
	if _, err := s.CancelSubscription("a"); err != nil {
		t.Fatal(err)
	}

	// 已登记按月取消但尚未到终止时刻：仍可查询，当月完整计费。
	e, err := s.EstimateCurrentBill("a")
	if err != nil {
		t.Fatalf("estimate while cancelling failed: %v", err)
	}
	if !e.Estimated || e.MonthlyFee != 1000 || e.IncludedUnits != 10 ||
		e.OverageFee != 500 || e.EstimatedTotalDue != 1650 {
		t.Fatalf("estimate while cancelling: %+v", e)
	}

	// 终止时刻到达后订阅已终止：返回无订阅错误，不输出预估。
	clk.t = utc(2026, 2, 1, 0, 0)
	if _, err := s.EstimateCurrentBill("a"); !errors.Is(err, ErrSubscriptionNotFound) {
		t.Fatalf("estimate after cancellation end: %v", err)
	}
	// 预估失败不留账单；一月正式出账仍按完整月计。
	b, err := s.CreateBill("a", jan(2026))
	if err != nil {
		t.Fatal(err)
	}
	if b.TotalDue != 1650 {
		t.Fatalf("january bill after end: %+v", b)
	}
}

func TestEstimateCurrentBillWhileSuspended(t *testing.T) {
	s, clk := newTestService(utc(2026, 1, 1, 0, 0))
	mustPlan(t, s, Plan{ID: "p", MonthlyFee: 1000, IncludedUnits: 10, OveragePrice: 100, TaxRateBasisPoints: 0})
	mustAccount(t, s, "a")
	if err := s.Subscribe("a", "p", utc(2026, 1, 1, 0, 0)); err != nil {
		t.Fatal(err)
	}
	// 二月 5 日（一月账单截止 2 月 8 日之前）先接收 5 单位二月用量。
	clk.t = utc(2026, 2, 5, 0, 0)
	if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "e-feb", At: utc(2026, 2, 5, 0, 0), Quantity: 5}); err != nil {
		t.Fatal(err)
	}
	// 过了截止时刻为一月出账：一月账单未付，账户欠费停用；订阅仍生效。
	clk.t = utc(2026, 2, 10, 0, 0)
	janBill, err := s.CreateBill("a", jan(2026))
	if err != nil {
		t.Fatal(err)
	}
	st, _ := s.Status("a")
	if !st.Subscribed || !st.Suspended {
		t.Fatalf("want subscribed+suspended, got %+v", st)
	}

	// 停用期间仍可查询预估，包含停用前已接收的二月累计 5。
	e, err := s.EstimateCurrentBill("a")
	if err != nil {
		t.Fatalf("estimate while suspended failed: %v", err)
	}
	if e.Period != feb(2026) || e.TotalUsage != 5 || e.MonthlyFee != 1000 || e.EstimatedTotalDue != 1000 {
		t.Fatalf("estimate while suspended: %+v", e)
	}
	// 查询本身不能解除停用，也不改变新用量被拒绝的规则。
	if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "e-new", At: utc(2026, 2, 10, 0, 0), Quantity: 1}); !errors.Is(err, ErrSuspended) {
		t.Fatalf("new usage after estimate: %v", err)
	}
	st, _ = s.Status("a")
	if !st.Suspended {
		t.Fatal("estimate cleared suspension")
	}
	// 预估没有改变欠费账单。
	cur, err := s.GetBill("a", jan(2026))
	if err != nil || cur.Balance != janBill.TotalDue || cur.Settled {
		t.Fatalf("overdue bill changed: %+v %v", cur, err)
	}

	// 结清后预估照常，且二月累计仍是 5（被拒收的事件未累计）。
	if _, err := s.RecordPayment("a", "pay-jan", jan(2026), janBill.TotalDue); err != nil {
		t.Fatal(err)
	}
	e, err = s.EstimateCurrentBill("a")
	if err != nil {
		t.Fatal(err)
	}
	if e.TotalUsage != 5 || e.EstimatedTotalDue != 1000 {
		t.Fatalf("estimate after payment: %+v", e)
	}
}

func TestEstimateCurrentBillErrors(t *testing.T) {
	s, clk := newTestService(utc(2026, 1, 15, 12, 0))
	mustPlan(t, s, Plan{ID: "p", MonthlyFee: 1000, IncludedUnits: 10, OveragePrice: 100, TaxRateBasisPoints: 1000})
	mustAccount(t, s, "never")
	mustAccount(t, s, "future")
	mustAccount(t, s, "ended")
	mustAccount(t, s, "gap")

	if err := s.Subscribe("future", "p", utc(2026, 1, 20, 12, 0)); err != nil {
		t.Fatal(err)
	}
	if err := s.Subscribe("ended", "p", utc(2026, 1, 1, 0, 0)); err != nil {
		t.Fatal(err)
	}
	if _, err := s.CancelSubscription("ended"); err != nil {
		t.Fatal(err)
	}

	if _, err := s.EstimateCurrentBill(""); !errors.Is(err, ErrInvalidArgument) {
		t.Fatalf("empty id: %v", err)
	}
	if _, err := s.EstimateCurrentBill("ghost"); !errors.Is(err, ErrAccountNotFound) {
		t.Fatalf("missing account: %v", err)
	}
	if _, err := s.EstimateCurrentBill("never"); !errors.Is(err, ErrSubscriptionNotFound) {
		t.Fatalf("never subscribed: %v", err)
	}
	// 提前登记、开通时刻尚未到达：订阅尚未生效，不提前预估。
	if _, err := s.EstimateCurrentBill("future"); !errors.Is(err, ErrSubscriptionNotActivated) {
		t.Fatalf("future activation: %v", err)
	}
	// 开通当天零点仍未到登记的具体时刻：同样尚未生效。
	clk.t = utc(2026, 1, 20, 0, 0)
	if _, err := s.EstimateCurrentBill("future"); !errors.Is(err, ErrSubscriptionNotActivated) {
		t.Fatalf("activation day midnight: %v", err)
	}
	// 恰好到达开通时刻即可预估。
	clk.t = utc(2026, 1, 20, 12, 0)
	if e, err := s.EstimateCurrentBill("future"); err != nil || !e.Estimated || e.MonthlyFee != 1000 {
		t.Fatalf("estimate at activation instant: %+v %v", e, err)
	}

	// 已登记取消、到达终止时刻后订阅终止。
	clk.t = utc(2026, 2, 1, 0, 0)
	if _, err := s.EstimateCurrentBill("ended"); !errors.Is(err, ErrSubscriptionNotFound) {
		t.Fatalf("ended subscription: %v", err)
	}

	// 旧订阅已终止、新订阅提前登记尚未开通：空档中按尚未生效处理。
	if err := s.Subscribe("gap", "p", utc(2026, 2, 10, 0, 0)); err != nil {
		// gap 账户没有旧订阅；直接登记未来开通即可。
		t.Fatal(err)
	}
	clk.t = utc(2026, 2, 5, 0, 0)
	if _, err := s.EstimateCurrentBill("gap"); !errors.Is(err, ErrSubscriptionNotActivated) {
		t.Fatalf("gap before future resubscribe: %v", err)
	}
	clk.t = utc(2026, 2, 10, 0, 0)
	if e, err := s.EstimateCurrentBill("gap"); err != nil || !e.Estimated {
		t.Fatalf("estimate after future activation: %+v %v", e, err)
	}
}

func TestEstimateCurrentBillOverflow(t *testing.T) {
	s, clk := newTestService(utc(2026, 1, 15, 12, 0))

	// 月费 maxInt64、1 单位超额即让税前合计溢出。
	mustPlan(t, s, Plan{ID: "p-sum", MonthlyFee: maxInt64, IncludedUnits: 0, OveragePrice: 1, TaxRateBasisPoints: 0})
	mustAccount(t, s, "a")
	if err := s.Subscribe("a", "p-sum", utc(2026, 1, 10, 0, 0)); err != nil {
		t.Fatal(err)
	}
	if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "e1", At: utc(2026, 1, 12, 0, 0), Quantity: 1}); err != nil {
		t.Fatal(err)
	}
	if _, err := s.EstimateCurrentBill("a"); !errors.Is(err, ErrOverflow) {
		t.Fatalf("subtotal overflow: %v", err)
	}

	// 税前合法、含税总额溢出。
	mustPlan(t, s, Plan{ID: "p-tax", MonthlyFee: 9000000000000000000, IncludedUnits: 0, OveragePrice: 0, TaxRateBasisPoints: 1000})
	mustAccount(t, s, "b")
	if err := s.Subscribe("b", "p-tax", utc(2026, 1, 10, 0, 0)); err != nil {
		t.Fatal(err)
	}
	if _, err := s.EstimateCurrentBill("b"); !errors.Is(err, ErrOverflow) {
		t.Fatalf("total overflow: %v", err)
	}

	// 溢出时不返回部分金额、不留账单、不改用量，可重试。
	if _, err := s.GetBill("a", jan(2026)); !errors.Is(err, ErrBillNotFound) {
		t.Fatalf("overflow left a bill: %v", err)
	}
	if u, _ := s.MonthlyUsage("a", jan(2026)); u.Total != 1 {
		t.Fatalf("usage changed: %d", u.Total)
	}
	if _, err := s.EstimateCurrentBill("a"); !errors.Is(err, ErrOverflow) {
		t.Fatal("retry estimate lost overflow")
	}

	// 计税中间乘积可超 int64，但最终金额合法时预估必须精确完成。
	mustPlan(t, s, Plan{ID: "p-large", MonthlyFee: 8000000000000000005, IncludedUnits: 0, OveragePrice: 0, TaxRateBasisPoints: 1000})
	mustAccount(t, s, "c")
	if err := s.Subscribe("c", "p-large", utc(2026, 1, 10, 0, 0)); err != nil {
		t.Fatal(err)
	}
	e, err := s.EstimateCurrentBill("c")
	if err != nil {
		t.Fatalf("large but legal estimate: %v", err)
	}
	if e.MonthlyFee != 8000000000000000005 || e.Tax != 800000000000000001 || e.EstimatedTotalDue != 8800000000000000006 {
		t.Fatalf("large estimate amounts: %+v", e)
	}

	// 时钟推进不影响上述判断的独立性（避免 unused 警告，同时验证跨月后
	// 一月仍未因预估而关闭：二月账户 c 的预估是零用量整月费）。
	clk.t = utc(2026, 2, 1, 0, 0)
	if _, err := s.GetBill("c", jan(2026)); !errors.Is(err, ErrBillNotFound) {
		t.Fatalf("january bill should not exist after estimates")
	}
}

# 订阅、用量与账单

在本机运行的订阅、用量与账单服务，以 Go 包 `meter` 提供，数据保存在内存中。

## 使用

```bash
go test ./...
```

## 能力

- `NewService` / `NewServiceWithClock`：创建并发安全的服务（后者可注入时钟）。
- `CreateAccount`：创建业务账户，标识唯一。
- `CreatePlan` / `UpdatePlan`：维护套餐（月费、包含用量、超额单价、万分比税率）。修改套餐定义只影响之后新保存的条件快照（之后开通的订阅与之后新接受的换套餐安排），不改写已开通订阅保存的快照，也不改写已接受安排锁定的条件。
- `Subscribe`：开通订阅并保存当时的套餐条件快照；每账户一份有效订阅；订阅按月终止后可用同一入口重新开通。允许登记开通时刻晚于当前时刻的订阅：到达实际开通时刻前查询显示未生效（`Subscribed` 为 false、`CurrentTerms` 为零值，亦无待换套餐安排与待取消终止时刻），此期间再次开通按已有订阅拒绝，安排换套餐、登记取消返回订阅尚未生效的错误；以实际开通时刻为界（同一瞬间与时区无关），不按开通月份提前生效，到达后直接查询即显示登记时保存的完整套餐条件，等待期间修改套餐不改变该快照。旧订阅终止后登记未来重新开通的空档同样不显示生效套餐，历史用量与账单继续可查。
- `SchedulePlanChange` / `CancelPlanChange`：安排或取消从下一个 UTC 自然月起换用另一套餐；安排时锁定目标套餐完整条件快照，每账户至多一条待生效安排。
- `CancelSubscription` / `UndoCancelSubscription`：登记按月取消（终止时刻为请求时刻的下一个 UTC 自然月月初，当月仍按完整月费与额度计费）或在生效前撤回；重复取消返回原终止时刻。
- `RecordEvent`：上报用量，按发生时刻归入 UTC 自然月账期，事件时刻须落在某段实际订阅期间（开通计入、终止不计入）；账户内事件标识去重。账期结束后、出账前仍可补报晚到用量（详见下文“用量补报”）。
- `CreateBill` / `GetBill`：为已结束且被某段订阅覆盖的账期出账，完全无订阅的空档月份失败；重复出账得到同一张账单；每张账单按该账期当时适用的套餐条件计费。
- `RecordPayment`：分次登记付款，账户内付款标识去重（详见下文“付款登记”）。
- `MonthlyUsage` / `Status`：查询各月累计用量、当前生效套餐条件（订阅以实际开通时刻为界，等待开通期间为零值）、待生效安排、已安排的终止时刻、账单余额与欠费停用状态（等待开通不清旧欠费，`Subscribed` 与停用分别表示订阅是否生效与是否存在到期未结清账单）。月度历史列表的收录规则详见下文“月度历史查询”。
- `EstimateCurrentBill`：账期尚未结束时查询当前 UTC 自然月截至查询时刻的**预计账单**（结果以 `Estimated=true` 明确标为预估），不必先出账；纯读操作，不保存账单、不关闭当月、不产生欠费（详见下文“账期内预计费用查询”）。

金额与用量均为非负 `int64`，金额单位为分，税率为万分比（0–10000）。
到期欠费的账户会被停用，结清全部到期欠费账单后恢复；结清债务不复活已取消的订阅。
换套餐在生效月月初零点自动生效：安排当月仍按旧套餐收取完整月费、提供完整额度，
不按天补差、不迁移本月用量；已生成账单的金额与税额不因后续切换或取消而变化。

按月取消订阅在请求时刻的下一个 UTC 自然月月初零点终止订阅：当月照常接收用量并
按完整月计费，不按天退款；登记取消清除尚未生效的换套餐安排，等待取消期间拒绝新
安排，撤回取消不恢复被清除的安排。终止时刻到达即无有效订阅（无需上报用量或
出账），历史用量与账单继续可查；终止后可通过 `Subscribe` 重新开通（开通时刻不得
早于上次终止时刻），支持多次取消与重新开通，旧月份归属与计价不被后来订阅覆盖。

## 修改套餐定义与安排换套餐

`UpdatePlan` 与 `SchedulePlanChange` 是两类不同的操作，不要混淆：

- **修改套餐定义**（`UpdatePlan`）只影响之后新保存的条件快照：之后开通的
  订阅、之后新接受的换套餐安排会按修改后的定义取得条件。它不会直接改写
  任何账户正在使用的条件——已开通订阅继续使用开通时保存的快照；也不会
  改写此前已接受的换套餐安排——安排锁定的条件保持安排被接受时的取值。
- **安排换套餐**（`SchedulePlanChange`）针对具体账户：被接受时锁定目标
  套餐当时的完整条件（月费、包含额度、超额单价、税率）与生效账期（请求
  被接受时的下一个 UTC 自然月），之后修改套餐定义不影响该安排。

安排生效前再次安排同一目标套餐，返回的是原安排（`Created` 为 `false`），
不重新取价——即使套餐定义在此期间已被修改，也不要把它当成按新定义重新
安排。这一结果仅限于安排尚未生效时；安排生效后目标套餐已成为当前套餐，
再安排它仍按现有规则返回 `ErrPlanChangeSamePlan`。到达生效账期月初零点
（UTC）后，直接查询即显示安排锁定的条件，待生效安排消失，无须先上报
用量或生成账单。

账单只能在各自账期结束后生成；每张账单按该账期当时适用的条件计费：安排
当月仍按旧套餐收完整月费、给完整额度，生效月起按锁定的目标套餐条件计费，
修改后的套餐定义不会混入已锁定安排的计费。已生成的账单不因后续出账或
定义修改而变化。欠费停用规则保持不变：上一账期账单到期未结清会阻止上报
新用量，示例在付款截止后先正常登记付款再上报。

下面的示例只用公开入口即可运行：通过 `NewServiceWithClock` 注入可推进的
时钟，输出不依赖运行当天日期。账户 `acct-switch` 2026-01-01 00:00 UTC
开通 plan-a（月费 1000 分、包含 10 单位、超额单价 100 分、税率 10%），
一月用量 15 单位；2026-01-15 12:00 UTC 安排二月换到 plan-b（当时定义为
月费 2000 分、包含 20 单位、超额单价 200 分、税率 6%）。随后 `UpdatePlan`
把 plan-b 改为月费 5000 分、包含 5 单位、超额单价 900 分、税率 25%，
再次安排同一目标仍返回原安排。二月用量 25 单位；一月账单应付 1650 分
（月费 1000 + 超额 5×100 + 税 150），二月账单按锁定的 plan-b 条件应付
3180 分（月费 2000 + 超额 5×200 + 税 180），修改后的定义没有混入这次
切换的计费。该示例以 Example 测试形式保存在
`meter/plan_change_example_test.go`，`go test ./...` 会校验其输出：

```go
const accountID = "acct-switch"
jan := meter.MonthOf(mustParseTime("2026-01-01T00:00:00Z"))
feb := meter.MonthOf(mustParseTime("2026-02-01T00:00:00Z"))

// 可推进的时钟：初始当前时刻为 2026-01-15 12:00 UTC（一月中旬），
// 之后逐段推进到二月、三月，复制后在任何真实日期运行结果都相同。
now := mustParseTime("2026-01-15T12:00:00Z")
s := meter.NewServiceWithClock(func() time.Time { return now })

if err := s.CreateAccount(accountID); err != nil {
    panic(err)
}
// 套餐 plan-a：月费 1000 分、包含 10 单位、超额单价 100 分、税率 10%。
if err := s.CreatePlan(meter.Plan{
    ID: "plan-a", MonthlyFee: 1000, IncludedUnits: 10,
    OveragePrice: 100, TaxRateBasisPoints: 1000,
}); err != nil {
    panic(err)
}
// 套餐 plan-b 当前定义：月费 2000 分、包含 20 单位、超额单价 200 分、税率 6%。
if err := s.CreatePlan(meter.Plan{
    ID: "plan-b", MonthlyFee: 2000, IncludedUnits: 20,
    OveragePrice: 200, TaxRateBasisPoints: 600,
}); err != nil {
    panic(err)
}
// 账户一月起使用 plan-a。
if err := s.Subscribe(accountID, "plan-a", mustParseTime("2026-01-01T00:00:00Z")); err != nil {
    panic(err)
}

// 一月用量 15 单位，超出 plan-a 包含的 10 单位。
ev, err := s.RecordEvent(meter.Event{
    AccountID: accountID, EventID: "e-jan",
    At: mustParseTime("2026-01-10T00:00:00Z"), Quantity: 15,
})
if err != nil {
    panic(err)
}
fmt.Printf("event e-jan accepted=%t period=%s\n", ev.Accepted, ev.Period)

// 一月中旬安排二月换到 plan-b：安排被接受时锁定目标套餐当时的
// 完整条件与生效账期（请求被接受时的下一个 UTC 自然月）。
r, err := s.SchedulePlanChange(accountID, "plan-b")
if err != nil {
    panic(err)
}
fmt.Printf("schedule    created=%t target=%s effective=%s monthlyFee=%d includedUnits=%d overagePrice=%d taxRateBasisPoints=%d\n",
    r.Created, r.Change.TargetPlanID, r.Change.EffectivePeriod,
    r.Change.Terms.MonthlyFee, r.Change.Terms.IncludedUnits,
    r.Change.Terms.OveragePrice, r.Change.Terms.TaxRateBasisPoints)

// 安排当月仍按旧套餐：查询仍显示 plan-a，待生效安排为 plan-b。
st, err := s.Status(accountID)
if err != nil {
    panic(err)
}
fmt.Printf("status      current=%s monthlyFee=%d pending=%s pendingEffective=%s\n",
    st.CurrentTerms.PlanID, st.CurrentTerms.MonthlyFee,
    st.PendingChange.TargetPlanID, st.PendingChange.EffectivePeriod)

// 修改 plan-b 的定义：月费、包含额度、超额单价、税率全部改变。
// 修改只影响之后新保存的条件快照，不改写已接受的安排。
if err := s.UpdatePlan(meter.Plan{
    ID: "plan-b", MonthlyFee: 5000, IncludedUnits: 5,
    OveragePrice: 900, TaxRateBasisPoints: 2500,
}); err != nil {
    panic(err)
}

// 再次安排同一个目标 plan-b：返回原安排，Created=false，条件仍是
// 首次安排时锁定的快照，不按修改后的定义重新取价。
r, err = s.SchedulePlanChange(accountID, "plan-b")
if err != nil {
    panic(err)
}
fmt.Printf("reschedule  created=%t target=%s effective=%s monthlyFee=%d includedUnits=%d overagePrice=%d taxRateBasisPoints=%d\n",
    r.Created, r.Change.TargetPlanID, r.Change.EffectivePeriod,
    r.Change.Terms.MonthlyFee, r.Change.Terms.IncludedUnits,
    r.Change.Terms.OveragePrice, r.Change.Terms.TaxRateBasisPoints)

// 待生效安排的条件也没有被修改后的定义改写。
st, err = s.Status(accountID)
if err != nil {
    panic(err)
}
fmt.Printf("after update current=%s pending=%s pendingMonthlyFee=%d pendingTaxRateBasisPoints=%d\n",
    st.CurrentTerms.PlanID, st.PendingChange.TargetPlanID,
    st.PendingChange.Terms.MonthlyFee, st.PendingChange.Terms.TaxRateBasisPoints)

// 推进到 2026-02-01 00:00 UTC（二月月初零点）：安排自动生效，
// 直接查询即显示锁定的 plan-b 条件，待生效安排消失，
// 无须先上报用量或生成账单。
now = mustParseTime("2026-02-01T00:00:00Z")
st, err = s.Status(accountID)
if err != nil {
    panic(err)
}
fmt.Printf("status      current=%s monthlyFee=%d includedUnits=%d overagePrice=%d taxRateBasisPoints=%d pending=%v\n",
    st.CurrentTerms.PlanID, st.CurrentTerms.MonthlyFee,
    st.CurrentTerms.IncludedUnits, st.CurrentTerms.OveragePrice,
    st.CurrentTerms.TaxRateBasisPoints, st.PendingChange)

// “重复安排返回原安排”仅限于安排尚未生效时：生效后 plan-b 已是
// 当前套餐，再安排它按现有规则返回同套餐错误。
_, err = s.SchedulePlanChange(accountID, "plan-b")
fmt.Printf("same plan   errSamePlan=%t\n", errors.Is(err, meter.ErrPlanChangeSamePlan))

// 一月账期已结束，为一月出账：仍按 plan-a 收完整月费、给完整额度。
// 用量 15，超额 5 × 100 = 500 分；税 (1000+500) × 10% = 150 分。
janBill, err := s.CreateBill(accountID, jan)
if err != nil {
    panic(err)
}
fmt.Printf("bill jan    plan=%s totalUsage=%d monthlyFee=%d includedUnits=%d overageUnits=%d overageFee=%d tax=%d totalDue=%d dueAt=%s\n",
    janBill.Terms.PlanID, janBill.TotalUsage, janBill.MonthlyFee,
    janBill.IncludedUnits, janBill.OverageUnits, janBill.OverageFee,
    janBill.Tax, janBill.TotalDue, janBill.DueAt.Format(time.RFC3339))

// 一月账单截止 2026-02-08 00:00 UTC。当前时刻推进到 2 月 10 日：
// 若不结清，欠费停用会阻止二月上报新用量，因此先正常登记付款。
now = mustParseTime("2026-02-10T00:00:00Z")
pay, err := s.RecordPayment(accountID, "pay-jan", jan, janBill.TotalDue)
if err != nil {
    panic(err)
}
fmt.Printf("payment     registered=%t paymentID=%s amount=%d billBalance=%d settled=%t\n",
    pay.Registered, pay.Payment.PaymentID, pay.Payment.Amount, pay.BillBalance, pay.Settled)

// 二月用量 25 单位，超出锁定的 plan-b 包含的 20 单位。
ev, err = s.RecordEvent(meter.Event{
    AccountID: accountID, EventID: "e-feb",
    At: mustParseTime("2026-02-10T00:00:00Z"), Quantity: 25,
})
if err != nil {
    panic(err)
}
fmt.Printf("event e-feb accepted=%t period=%s\n", ev.Accepted, ev.Period)

// 二月账期结束后为二月出账：按安排时锁定的 plan-b 条件计费
// （月费 2000 分，不是修改后的 5000 分）。用量 25，超额
// 5 × 200 = 1000 分；税 (2000+1000) × 6% = 180 分。
now = mustParseTime("2026-03-01T00:00:00Z")
febBill, err := s.CreateBill(accountID, feb)
if err != nil {
    panic(err)
}
fmt.Printf("bill feb    plan=%s totalUsage=%d monthlyFee=%d includedUnits=%d overageUnits=%d overageFee=%d tax=%d totalDue=%d dueAt=%s\n",
    febBill.Terms.PlanID, febBill.TotalUsage, febBill.MonthlyFee,
    febBill.IncludedUnits, febBill.OverageUnits, febBill.OverageFee,
    febBill.Tax, febBill.TotalDue, febBill.DueAt.Format(time.RFC3339))

// 二月出账后查询一月账单：超额费用、税额与总应付保持原样。
janAgain, err := s.GetBill(accountID, jan)
if err != nil {
    panic(err)
}
fmt.Printf("get bill jan plan=%s totalUsage=%d overageFee=%d tax=%d totalDue=%d\n",
    janAgain.Terms.PlanID, janAgain.TotalUsage, janAgain.OverageFee,
    janAgain.Tax, janAgain.TotalDue)
```

输出（`mustParseTime` 用 `time.Parse(time.RFC3339, value)` 解析上述常量即可）：

```text
event e-jan accepted=true period=2026-01
schedule    created=true target=plan-b effective=2026-02 monthlyFee=2000 includedUnits=20 overagePrice=200 taxRateBasisPoints=600
status      current=plan-a monthlyFee=1000 pending=plan-b pendingEffective=2026-02
reschedule  created=false target=plan-b effective=2026-02 monthlyFee=2000 includedUnits=20 overagePrice=200 taxRateBasisPoints=600
after update current=plan-a pending=plan-b pendingMonthlyFee=2000 pendingTaxRateBasisPoints=600
status      current=plan-b monthlyFee=2000 includedUnits=20 overagePrice=200 taxRateBasisPoints=600 pending=<nil>
same plan   errSamePlan=true
bill jan    plan=plan-a totalUsage=15 monthlyFee=1000 includedUnits=10 overageUnits=5 overageFee=500 tax=150 totalDue=1650 dueAt=2026-02-08T00:00:00Z
